/* Small offline collapse helper; official full Bootstrap bundle can be substituted. */
document.addEventListener('click',function(e){const b=e.target.closest('[data-bs-toggle="collapse"]');if(!b)return;const t=document.querySelector(b.getAttribute('data-bs-target'));if(t){t.classList.toggle('show');b.setAttribute('aria-expanded',t.classList.contains('show')?'true':'false')}});